new='''/// Where the tokenizer is within a `key=value` pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: a timestamp, a key or a word comes next.
    BetweenTokens,
    /// Just after `key=`: the value comes next.
    AfterEquals,
    /// An error was returned; nothing more is produced.
    Failed,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::BetweenTokens }
    }

    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }

    /// Reads the next token; `Ok(None)` means the line is used up.
    fn read_next(&mut self) -> Result<Option<Token<'a>>, LexError> {
        match self.state {
            State::BetweenTokens => self.read_token_between_pairs(),
            State::AfterEquals => self.read_value().map(Some),
            State::Failed => Ok(None),
        }
    }

    fn read_token_between_pairs(&mut self) -> Result<Option<Token<'a>>, LexError> {
        let bytes = self.bytes();
        let start = skip_blanks(bytes, self.pos);
        self.pos = start;
        let Some(&first) = bytes.get(start) else {
            return Ok(None);
        };
        let token = match first {
            b'[' => self.read_timestamp(start)?,
            b'"' => return Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => return Err(LexError::EmptyKey { pos: start }),
            _ => self.read_key_or_word(start)?,
        };
        Ok(Some(token))
    }

    /// `open` is the position of the `[`.
    fn read_timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let text_start = open + 1;
        let close = find_timestamp_end(bytes, text_start, open)?;
        require_separator_after(bytes, close)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&self.src[text_start..close]))
    }

    fn read_key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let end = scan_unquoted(bytes, start, StopAt::BlankOrEquals)?;
        let text = &self.src[start..end];
        if bytes.get(end) == Some(&b'=') {
            self.state = State::AfterEquals;
            self.pos = end + 1;
            Ok(Token::Key(text))
        } else {
            self.pos = end;
            Ok(Token::Word(text))
        }
    }

    fn read_value(&mut self) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let start = self.pos;
        let token = match bytes.get(start) {
            None => Token::Bare(&self.src[start..start]),
            Some(&byte) if is_blank(byte) => Token::Bare(&self.src[start..start]),
            Some(b'"') => return self.read_quoted(start),
            Some(_) => {
                let end = scan_unquoted(bytes, start, StopAt::Blank)?;
                self.pos = end;
                Token::Bare(&self.src[start..end])
            }
        };
        self.state = State::BetweenTokens;
        Ok(token)
    }

    /// `open` is the position of the opening `"`.
    fn read_quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.bytes();
        let text_start = open + 1;
        let close = find_closing_quote(bytes, text_start, open)?;
        require_separator_after(bytes, close)?;
        self.state = State::BetweenTokens;
        self.pos = close + 1;
        Ok(Token::Quoted(&self.src[text_start..close]))
    }

    fn fail(&mut self) {
        self.state = State::Failed;
        self.pos = self.src.len();
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = self.read_next();
        if result.is_err() {
            self.fail();
        }
        result.transpose()
    }
}

#[inline(always)]
fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\\t'
}

fn skip_blanks(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && is_blank(bytes[pos]) {
        pos += 1;
    }
    pos
}

/// Position of the `]` closing a timestamp whose text starts at `from`.
fn find_timestamp_end(bytes: &[u8], from: usize, open: usize) -> Result<usize, LexError> {
    for (pos, &byte) in bytes.iter().enumerate().skip(from) {
        match byte {
            b']' => return Ok(pos),
            b'[' => return Err(LexError::NestedBracket { pos }),
            _ => {}
        }
    }
    Err(LexError::UnterminatedTimestamp { pos: open })
}

/// Position of the `"` closing a quoted value whose text starts at `from`.
fn find_closing_quote(bytes: &[u8], from: usize, open: usize) -> Result<usize, LexError> {
    let unterminated = LexError::UnterminatedQuote { pos: open };
    let mut pos = from;
    loop {
        match *bytes.get(pos).ok_or(unterminated)? {
            b'"' => return Ok(pos),
            b'\\\\' => {
                let escaped = *bytes.get(pos + 1).ok_or(unterminated)?;
                if !is_valid_escape(escaped) {
                    return Err(LexError::InvalidEscape { pos });
                }
                pos += 2;
            }
            _ => pos += 1,
        }
    }
}

fn is_valid_escape(byte: u8) -> bool {
    matches!(byte, b'"' | b'\\\\' | b'n' | b't')
}

/// A token must be followed by a blank or the end of the line.
fn require_separator_after(bytes: &[u8], token_end: usize) -> Result<(), LexError> {
    match bytes.get(token_end + 1) {
        Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos: token_end + 1 }),
        _ => Ok(()),
    }
}

/// What ends an unquoted run besides a quote, which is never allowed inside one.
#[derive(Clone, Copy)]
enum StopAt {
    Blank,
    BlankOrEquals,
}

/// End of the unquoted run starting at `from`.
#[inline(always)]
fn scan_unquoted(bytes: &[u8], from: usize, stop_at: StopAt) -> Result<usize, LexError> {
    let mut pos = from;
    while let Some(&byte) = bytes.get(pos) {
        let stops = is_blank(byte) || (byte == b'=' && matches!(stop_at, StopAt::BlankOrEquals));
        if stops {
            break;
        }
        if byte == b'"' {
            return Err(LexError::UnexpectedQuote { pos });
        }
        pos += 1;
    }
    Ok(pos)
}
