fn same_as_old() {
    let alphabet = [b'[', b']', b'"', b'=', b'\\', b' ', b'\t', b'a', b'n'];
    for len in 0..=8u32 {
        let total = (alphabet.len() as u64).pow(len);
        for mut code in 0..total {
            let mut v = Vec::new();
            for _ in 0..len {
                v.push(alphabet[(code % 9) as usize]);
                code /= 9;
            }
            let s = String::from_utf8(v).unwrap();
            let a: Vec<_> = tokenize(&s).map(|r| r.map(|t| format!("{t:?}"))).collect();
            let b: Vec<_> = old::tokenize(&s).map(|r| r.map(|t| format!("{t:?}"))).collect();
            assert_eq!(a, b, "{s:?}");
        }
    }
}

